/// TestMessage Packet
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TestMessagePacket {
    pub header: Header,
    pub test_block1: TestMessageTestBlock1Block,
    pub neighbor_block: Vec<TestMessageNeighborBlockBlock>,
}

impl Packet for TestMessagePacket {
    fn packet_type(&self) -> PacketType {
        PacketType::TestMessage
    }
    fn serialize(&self, buf: &mut BytesMut) {
        self.header.serialize(buf);
        self.test_block1.serialize(buf);
        for block in &self.neighbor_block {
            block.serialize(buf);
        }
        self.header.write_acks(buf);
    }

    fn from_bytes(header: Header, buf: &mut Bytes) -> Result<Self, io::Error> {
        let packet = TestMessagePacket {
            header,
            test_block1: TestMessageTestBlock1Block::from_bytes(buf)?,
            neighbor_block: {
                let count = 4;
                let mut blocks = Vec::with_capacity(count);
                for _ in 0..count {
                    blocks.push(TestMessageNeighborBlockBlock::from_bytes(buf)?);
                }
                blocks
            },
        };
        Ok(packet)
    }
}

