/// PacketAck Packet
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PacketAckPacket {
    pub header: Header,
    pub packets: Vec<PacketAckPacketsBlock>,
}

impl Packet for PacketAckPacket {
    fn packet_type(&self) -> PacketType {
        PacketType::PacketAck
    }
    fn serialize(&self, buf: &mut BytesMut) {
        self.header.serialize(buf);
        buf.put_u8(self.packets.len() as u8);
        for block in &self.packets {
            block.serialize(buf);
        }
        self.header.write_acks(buf);
    }

    fn from_bytes(header: Header, buf: &mut Bytes) -> Result<Self, io::Error> {
        let packet = PacketAckPacket {
            header,
            packets: {
                let count = r_u8(buf)? as usize;
                let mut blocks = Vec::with_capacity(count);
                for _ in 0..count {
                    blocks.push(PacketAckPacketsBlock::from_bytes(buf)?);
                }
                blocks
            },
        };
        Ok(packet)
    }
}

