#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TelehubInfoTelehubBlockBlock {
    pub object_i_d: UUID,
    pub object_name: Vec<u8>,
    pub telehub_pos: Vector3,
    pub telehub_rot: Quaternion,
}

impl TelehubInfoTelehubBlockBlock {
    pub fn serialize(&self, buf: &mut BytesMut) {
        buf.put_slice(self.object_i_d.as_bytes());
        buf.put_u8(self.object_name.len() as u8);
        buf.put_slice(&self.object_name);
        buf.put_f32_le(self.telehub_pos.x);
        buf.put_f32_le(self.telehub_pos.y);
        buf.put_f32_le(self.telehub_pos.z);
        buf.put_f32_le(self.telehub_rot.x);
        buf.put_f32_le(self.telehub_rot.y);
        buf.put_f32_le(self.telehub_rot.z);
    }

    pub fn from_bytes(buf: &mut Bytes) -> Result<Self, io::Error> {
        Ok(TelehubInfoTelehubBlockBlock {
            object_i_d: {
                let mut bytes = [0u8; 16];
                r_copy(buf, &mut bytes)?;
                UUID::from_bytes(bytes)
            },
            object_name: {
                let len = r_u8(buf)? as usize;
                let mut data = vec![0u8; len];
                r_copy(buf, &mut data)?;
                data
            },
            telehub_pos: Vector3::new(r_f32_le(buf)?, r_f32_le(buf)?, r_f32_le(buf)?),
            telehub_rot: {
                let x = r_f32_le(buf)?;
                let y = r_f32_le(buf)?;
                let z = r_f32_le(buf)?;
                let xyzsum = 1.0 - x * x - y * y - z * z;
                let w = if xyzsum > 0.0 { xyzsum.sqrt() } else { 0.0 };
                Quaternion::new(x, y, z, w)
            },
        })
    }
}

