/// DirLandReply Packet
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DirLandReplyPacket {
    pub header: Header,
    pub agent_data: DirLandReplyAgentDataBlock,
    pub query_data: DirLandReplyQueryDataBlock,
    pub query_replies: Vec<DirLandReplyQueryRepliesBlock>,
}

impl Packet for DirLandReplyPacket {
    fn packet_type(&self) -> PacketType {
        PacketType::DirLandReply
    }
    fn serialize(&self, buf: &mut BytesMut) {
        self.header.serialize(buf);
        self.agent_data.serialize(buf);
        self.query_data.serialize(buf);
        buf.put_u8(self.query_replies.len() as u8);
        for block in &self.query_replies {
            block.serialize(buf);
        }
        self.header.write_acks(buf);
    }

    fn from_bytes(header: Header, buf: &mut Bytes) -> Result<Self, io::Error> {
        let packet = DirLandReplyPacket {
            header,
            agent_data: DirLandReplyAgentDataBlock::from_bytes(buf)?,
            query_data: DirLandReplyQueryDataBlock::from_bytes(buf)?,
            query_replies: {
                let count = r_u8(buf)? as usize;
                let mut blocks = Vec::with_capacity(count);
                for _ in 0..count {
                    blocks.push(DirLandReplyQueryRepliesBlock::from_bytes(buf)?);
                }
                blocks
            },
        };
        Ok(packet)
    }
}

