#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AgentUpdateAgentDataBlock {
    pub agent_i_d: UUID,
    pub session_i_d: UUID,
    pub body_rotation: Quaternion,
    pub head_rotation: Quaternion,
    pub state: u8,
    pub camera_center: Vector3,
    pub camera_at_axis: Vector3,
    pub camera_left_axis: Vector3,
    pub camera_up_axis: Vector3,
    pub far: f32,
    pub control_flags: u32,
    pub flags: u8,
}

impl AgentUpdateAgentDataBlock {
    pub fn serialize(&self, buf: &mut BytesMut) {
        buf.put_slice(self.agent_i_d.as_bytes());
        buf.put_slice(self.session_i_d.as_bytes());
        buf.put_f32_le(self.body_rotation.x);
        buf.put_f32_le(self.body_rotation.y);
        buf.put_f32_le(self.body_rotation.z);
        buf.put_f32_le(self.head_rotation.x);
        buf.put_f32_le(self.head_rotation.y);
        buf.put_f32_le(self.head_rotation.z);
        buf.put_u8(self.state);
        buf.put_f32_le(self.camera_center.x);
        buf.put_f32_le(self.camera_center.y);
        buf.put_f32_le(self.camera_center.z);
        buf.put_f32_le(self.camera_at_axis.x);
        buf.put_f32_le(self.camera_at_axis.y);
        buf.put_f32_le(self.camera_at_axis.z);
        buf.put_f32_le(self.camera_left_axis.x);
        buf.put_f32_le(self.camera_left_axis.y);
        buf.put_f32_le(self.camera_left_axis.z);
        buf.put_f32_le(self.camera_up_axis.x);
        buf.put_f32_le(self.camera_up_axis.y);
        buf.put_f32_le(self.camera_up_axis.z);
        buf.put_f32_le(self.far);
        buf.put_u32_le(self.control_flags);
        buf.put_u8(self.flags);
    }

    pub fn from_bytes(buf: &mut Bytes) -> Result<Self, io::Error> {
        Ok(AgentUpdateAgentDataBlock {
            agent_i_d: {
                let mut bytes = [0u8; 16];
                r_copy(buf, &mut bytes)?;
                UUID::from_bytes(bytes)
            },
            session_i_d: {
                let mut bytes = [0u8; 16];
                r_copy(buf, &mut bytes)?;
                UUID::from_bytes(bytes)
            },
            body_rotation: {
                let x = r_f32_le(buf)?;
                let y = r_f32_le(buf)?;
                let z = r_f32_le(buf)?;
                let xyzsum = 1.0 - x * x - y * y - z * z;
                let w = if xyzsum > 0.0 { xyzsum.sqrt() } else { 0.0 };
                Quaternion::new(x, y, z, w)
            },
            head_rotation: {
                let x = r_f32_le(buf)?;
                let y = r_f32_le(buf)?;
                let z = r_f32_le(buf)?;
                let xyzsum = 1.0 - x * x - y * y - z * z;
                let w = if xyzsum > 0.0 { xyzsum.sqrt() } else { 0.0 };
                Quaternion::new(x, y, z, w)
            },
            state: r_u8(buf)?,
            camera_center: Vector3::new(r_f32_le(buf)?, r_f32_le(buf)?, r_f32_le(buf)?),
            camera_at_axis: Vector3::new(r_f32_le(buf)?, r_f32_le(buf)?, r_f32_le(buf)?),
            camera_left_axis: Vector3::new(r_f32_le(buf)?, r_f32_le(buf)?, r_f32_le(buf)?),
            camera_up_axis: Vector3::new(r_f32_le(buf)?, r_f32_le(buf)?, r_f32_le(buf)?),
            far: r_f32_le(buf)?,
            control_flags: r_u32_le(buf)?,
            flags: r_u8(buf)?,
        })
    }
}

