#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ObjectAttachObjectDataBlock {
    pub object_local_i_d: u32,
    pub rotation: Quaternion,
}

impl ObjectAttachObjectDataBlock {
    pub fn serialize(&self, buf: &mut BytesMut) {
        buf.put_u32_le(self.object_local_i_d);
        buf.put_f32_le(self.rotation.x);
        buf.put_f32_le(self.rotation.y);
        buf.put_f32_le(self.rotation.z);
    }

    pub fn from_bytes(buf: &mut Bytes) -> Result<Self, io::Error> {
        Ok(ObjectAttachObjectDataBlock {
            object_local_i_d: r_u32_le(buf)?,
            rotation: {
                let x = r_f32_le(buf)?;
                let y = r_f32_le(buf)?;
                let z = r_f32_le(buf)?;
                let xyzsum = 1.0 - x * x - y * y - z * z;
                let w = if xyzsum > 0.0 { xyzsum.sqrt() } else { 0.0 };
                Quaternion::new(x, y, z, w)
            },
        })
    }
}

