#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AlertMessagePacket {
    pub header: Header,
    pub alert_data: AlertMessageAlertDataBlock,
    pub alert_info: Vec<AlertMessageAlertInfoBlock>,
    pub agent_info: Vec<AlertMessageAgentInfoBlock>,
}

impl Packet for AlertMessagePacket {
    fn packet_type(&self) -> PacketType {
        PacketType::AlertMessage
    }
    fn serialize(&self, buf: &mut BytesMut) {
        self.header.serialize(buf);
        self.alert_data.serialize(buf);
        buf.put_u8(self.alert_info.len() as u8);
        for block in &self.alert_info {
            block.serialize(buf);
        }
        buf.put_u8(self.agent_info.len() as u8);
        for block in &self.agent_info {
            block.serialize(buf);
        }
        self.header.write_acks(buf);
    }

    fn from_bytes(header: Header, buf: &mut Bytes) -> Result<Self, io::Error> {
        let packet = AlertMessagePacket {
            header,
            alert_data: AlertMessageAlertDataBlock::from_bytes(buf)?,
            alert_info: {
                let count = r_u8(buf)? as usize;
                let mut blocks = Vec::with_capacity(count);
                for _ in 0..count {
                    blocks.push(AlertMessageAlertInfoBlock::from_bytes(buf)?);
                }
                blocks
            },
            agent_info: {
                let count = r_u8(buf)? as usize;
                let mut blocks = Vec::with_capacity(count);
                for _ in 0..count {
                    blocks.push(AlertMessageAgentInfoBlock::from_bytes(buf)?);
                }
                blocks
            },
        };
        Ok(packet)
    }
}

