/// RegionHandshakeReply Packet
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RegionHandshakeReplyPacket {
    pub header: Header,
    pub agent_data: RegionHandshakeReplyAgentDataBlock,
    pub region_info: RegionHandshakeReplyRegionInfoBlock,
}

impl Packet for RegionHandshakeReplyPacket {
    fn packet_type(&self) -> PacketType {
        PacketType::RegionHandshakeReply
    }
    fn serialize(&self, buf: &mut BytesMut) {
        // RegionHandshakeReply is marked Zerocoded in the LLUDP template.
        // Firestorm only sets the flag when encoding actually reduces size.
        let mut unencoded = BytesMut::with_capacity(64);
        let mut header = self.header.clone();
        header.zerocoded = false;
        header.serialize(&mut unencoded);
        self.agent_data.serialize(&mut unencoded);
        self.region_info.serialize(&mut unencoded);
        header.write_acks(&mut unencoded);

        let encoded = crate::zerocoding::zero_encode(&unencoded);
        buf.extend_from_slice(&encoded);
    }

    fn from_bytes(header: Header, buf: &mut Bytes) -> Result<Self, io::Error> {
        let packet = RegionHandshakeReplyPacket {
            header,
            agent_data: RegionHandshakeReplyAgentDataBlock::from_bytes(buf)?,
            region_info: RegionHandshakeReplyRegionInfoBlock::from_bytes(buf)?,
        };
        Ok(packet)
    }
}

