/// ObjectUpdate Packet
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ObjectUpdatePacket {
    pub header: Header,
    pub region_data: ObjectUpdateRegionDataBlock,
    pub object_data: Vec<ObjectUpdateObjectDataBlock>,
}

impl Packet for ObjectUpdatePacket {
    fn packet_type(&self) -> PacketType {
        PacketType::ObjectUpdate
    }
    fn serialize(&self, buf: &mut BytesMut) {
        self.header.serialize(buf);
        self.region_data.serialize(buf);
        buf.put_u8(self.object_data.len() as u8);
        for block in &self.object_data {
            block.serialize(buf);
        }
        self.header.write_acks(buf);
    }

    fn from_bytes(header: Header, buf: &mut Bytes) -> Result<Self, io::Error> {
        let packet = ObjectUpdatePacket {
            header,
            region_data: ObjectUpdateRegionDataBlock::from_bytes(buf)?,
            object_data: {
                let count = r_u8(buf)? as usize;
                let mut blocks = Vec::with_capacity(count);
                for _ in 0..count {
                    blocks.push(ObjectUpdateObjectDataBlock::from_bytes(buf)?);
                }
                blocks
            },
        };
        Ok(packet)
    }
}

