#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AvatarSitResponseSitTransformBlock {
    pub auto_pilot: bool,
    pub sit_position: Vector3,
    pub sit_rotation: Quaternion,
    pub camera_eye_offset: Vector3,
    pub camera_at_offset: Vector3,
    pub force_mouselook: bool,
}

impl AvatarSitResponseSitTransformBlock {
    pub fn serialize(&self, buf: &mut BytesMut) {
        buf.put_u8(if self.auto_pilot { 1 } else { 0 });
        buf.put_f32_le(self.sit_position.x);
        buf.put_f32_le(self.sit_position.y);
        buf.put_f32_le(self.sit_position.z);
        buf.put_f32_le(self.sit_rotation.x);
        buf.put_f32_le(self.sit_rotation.y);
        buf.put_f32_le(self.sit_rotation.z);
        buf.put_f32_le(self.camera_eye_offset.x);
        buf.put_f32_le(self.camera_eye_offset.y);
        buf.put_f32_le(self.camera_eye_offset.z);
        buf.put_f32_le(self.camera_at_offset.x);
        buf.put_f32_le(self.camera_at_offset.y);
        buf.put_f32_le(self.camera_at_offset.z);
        buf.put_u8(if self.force_mouselook { 1 } else { 0 });
    }

    pub fn from_bytes(buf: &mut Bytes) -> Result<Self, io::Error> {
        Ok(AvatarSitResponseSitTransformBlock {
            auto_pilot: r_u8(buf)? != 0,
            sit_position: Vector3::new(r_f32_le(buf)?, r_f32_le(buf)?, r_f32_le(buf)?),
            sit_rotation: {
                let x = r_f32_le(buf)?;
                let y = r_f32_le(buf)?;
                let z = r_f32_le(buf)?;
                let xyzsum = 1.0 - x * x - y * y - z * z;
                let w = if xyzsum > 0.0 { xyzsum.sqrt() } else { 0.0 };
                Quaternion::new(x, y, z, w)
            },
            camera_eye_offset: Vector3::new(r_f32_le(buf)?, r_f32_le(buf)?, r_f32_le(buf)?),
            camera_at_offset: Vector3::new(r_f32_le(buf)?, r_f32_le(buf)?, r_f32_le(buf)?),
            force_mouselook: r_u8(buf)? != 0,
        })
    }
}

