#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AvatarGroupsReplyPacket {
    pub header: Header,
    pub agent_data: AvatarGroupsReplyAgentDataBlock,
    pub group_data: Vec<AvatarGroupsReplyGroupDataBlock>,
    pub new_group_data: AvatarGroupsReplyNewGroupDataBlock,
}

impl Packet for AvatarGroupsReplyPacket {
    fn packet_type(&self) -> PacketType {
        PacketType::AvatarGroupsReply
    }
    fn serialize(&self, buf: &mut BytesMut) {
        self.header.serialize(buf);
        self.agent_data.serialize(buf);
        buf.put_u8(self.group_data.len() as u8);
        for block in &self.group_data {
            block.serialize(buf);
        }
        self.new_group_data.serialize(buf);
        self.header.write_acks(buf);
    }

    fn from_bytes(header: Header, buf: &mut Bytes) -> Result<Self, io::Error> {
        let packet = AvatarGroupsReplyPacket {
            header,
            agent_data: AvatarGroupsReplyAgentDataBlock::from_bytes(buf)?,
            group_data: {
                let count = r_u8(buf)? as usize;
                let mut blocks = Vec::with_capacity(count);
                for _ in 0..count {
                    blocks.push(AvatarGroupsReplyGroupDataBlock::from_bytes(buf)?);
                }
                blocks
            },
            new_group_data: AvatarGroupsReplyNewGroupDataBlock::from_bytes(buf)?,
        };
        Ok(packet)
    }
}

