/// AvatarPicksReply Packet
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AvatarPicksReplyPacket {
    pub header: Header,
    pub agent_data: AvatarPicksReplyAgentDataBlock,
    pub data: Vec<AvatarPicksReplyDataBlock>,
}

impl Packet for AvatarPicksReplyPacket {
    fn packet_type(&self) -> PacketType {
        PacketType::AvatarPicksReply
    }
    fn serialize(&self, buf: &mut BytesMut) {
        self.header.serialize(buf);
        self.agent_data.serialize(buf);
        buf.put_u8(self.data.len() as u8);
        for block in &self.data {
            block.serialize(buf);
        }
        self.header.write_acks(buf);
    }

    fn from_bytes(header: Header, buf: &mut Bytes) -> Result<Self, io::Error> {
        let packet = AvatarPicksReplyPacket {
            header,
            agent_data: AvatarPicksReplyAgentDataBlock::from_bytes(buf)?,
            data: {
                let count = r_u8(buf)? as usize;
                let mut blocks = Vec::with_capacity(count);
                for _ in 0..count {
                    blocks.push(AvatarPicksReplyDataBlock::from_bytes(buf)?);
                }
                blocks
            },
        };
        Ok(packet)
    }
}

