/// ScriptTeleportRequest Packet
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ScriptTeleportRequestPacket {
    pub header: Header,
    pub data: ScriptTeleportRequestDataBlock,
    pub options: Vec<ScriptTeleportRequestOptionsBlock>,
}

impl Packet for ScriptTeleportRequestPacket {
    fn packet_type(&self) -> PacketType {
        PacketType::ScriptTeleportRequest
    }
    fn serialize(&self, buf: &mut BytesMut) {
        self.header.serialize(buf);
        self.data.serialize(buf);
        buf.put_u8(self.options.len() as u8);
        for block in &self.options {
            block.serialize(buf);
        }
        self.header.write_acks(buf);
    }

    fn from_bytes(header: Header, buf: &mut Bytes) -> Result<Self, io::Error> {
        let packet = ScriptTeleportRequestPacket {
            header,
            data: ScriptTeleportRequestDataBlock::from_bytes(buf)?,
            options: {
                let count = r_u8(buf)? as usize;
                let mut blocks = Vec::with_capacity(count);
                for _ in 0..count {
                    blocks.push(ScriptTeleportRequestOptionsBlock::from_bytes(buf)?);
                }
                blocks
            },
        };
        Ok(packet)
    }
}

