pub struct ParcelBuyDataBlock {
    pub group_i_d: UUID,
    pub is_group_owned: bool,
    pub remove_contribution: bool,
    pub local_i_d: i32,
    pub r#final: bool,
}

impl ParcelBuyDataBlock {
    pub fn serialize(&self, buf: &mut BytesMut) {
        buf.put_slice(self.group_i_d.as_bytes());
        buf.put_u8(if self.is_group_owned { 1 } else { 0 });
        buf.put_u8(if self.remove_contribution { 1 } else { 0 });
        buf.put_i32_le(self.local_i_d);
        buf.put_u8(if self.r#final { 1 } else { 0 });
    }

    pub fn from_bytes(buf: &mut Bytes) -> Result<Self, io::Error> {
        Ok(ParcelBuyDataBlock {
            group_i_d: {
                let mut bytes = [0u8; 16];
                r_copy(buf, &mut bytes)?;
                UUID::from_bytes(bytes)
            },
            is_group_owned: r_u8(buf)? != 0,
            remove_contribution: r_u8(buf)? != 0,
            local_i_d: r_i32_le(buf)?,
            r#final: r_u8(buf)? != 0,
        })
    }
}

