/// ParcelAccessListReply Packet
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ParcelAccessListReplyPacket {
    pub header: Header,
    pub data: ParcelAccessListReplyDataBlock,
    pub list: Vec<ParcelAccessListReplyListBlock>,
}

impl Packet for ParcelAccessListReplyPacket {
    fn packet_type(&self) -> PacketType {
        PacketType::ParcelAccessListReply
    }
    fn serialize(&self, buf: &mut BytesMut) {
        self.header.serialize(buf);
        self.data.serialize(buf);
        buf.put_u8(self.list.len() as u8);
        for block in &self.list {
            block.serialize(buf);
        }
        self.header.write_acks(buf);
    }

    fn from_bytes(header: Header, buf: &mut Bytes) -> Result<Self, io::Error> {
        let packet = ParcelAccessListReplyPacket {
            header,
            data: ParcelAccessListReplyDataBlock::from_bytes(buf)?,
            list: {
                let count = r_u8(buf)? as usize;
                let mut blocks = Vec::with_capacity(count);
                for _ in 0..count {
                    blocks.push(ParcelAccessListReplyListBlock::from_bytes(buf)?);
                }
                blocks
            },
        };
        Ok(packet)
    }
}

