/// ChildAgentUpdate Packet
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ChildAgentUpdatePacket {
    pub header: Header,
    pub agent_data: ChildAgentUpdateAgentDataBlock,
    pub group_data: Vec<ChildAgentUpdateGroupDataBlock>,
    pub animation_data: Vec<ChildAgentUpdateAnimationDataBlock>,
    pub granter_block: Vec<ChildAgentUpdateGranterBlockBlock>,
    pub n_v_pair_data: Vec<ChildAgentUpdateNVPairDataBlock>,
    pub visual_param: Vec<ChildAgentUpdateVisualParamBlock>,
    pub agent_access: Vec<ChildAgentUpdateAgentAccessBlock>,
    pub agent_info: Vec<ChildAgentUpdateAgentInfoBlock>,
    pub agent_inventory_host: Vec<ChildAgentUpdateAgentInventoryHostBlock>,
}

impl Packet for ChildAgentUpdatePacket {
    fn packet_type(&self) -> PacketType {
        PacketType::ChildAgentUpdate
    }
    fn serialize(&self, buf: &mut BytesMut) {
        self.header.serialize(buf);
        self.agent_data.serialize(buf);
        buf.put_u8(self.group_data.len() as u8);
        for block in &self.group_data {
            block.serialize(buf);
        }
        buf.put_u8(self.animation_data.len() as u8);
        for block in &self.animation_data {
            block.serialize(buf);
        }
        buf.put_u8(self.granter_block.len() as u8);
        for block in &self.granter_block {
            block.serialize(buf);
        }
        buf.put_u8(self.n_v_pair_data.len() as u8);
        for block in &self.n_v_pair_data {
            block.serialize(buf);
        }
        buf.put_u8(self.visual_param.len() as u8);
        for block in &self.visual_param {
            block.serialize(buf);
        }
        buf.put_u8(self.agent_access.len() as u8);
        for block in &self.agent_access {
            block.serialize(buf);
        }
        buf.put_u8(self.agent_info.len() as u8);
        for block in &self.agent_info {
            block.serialize(buf);
        }
        buf.put_u8(self.agent_inventory_host.len() as u8);
        for block in &self.agent_inventory_host {
            block.serialize(buf);
        }
        self.header.write_acks(buf);
    }

    fn from_bytes(header: Header, buf: &mut Bytes) -> Result<Self, io::Error> {
        let packet = ChildAgentUpdatePacket {
            header,
            agent_data: ChildAgentUpdateAgentDataBlock::from_bytes(buf)?,
            group_data: {
                let count = r_u8(buf)? as usize;
                let mut blocks = Vec::with_capacity(count);
                for _ in 0..count {
                    blocks.push(ChildAgentUpdateGroupDataBlock::from_bytes(buf)?);
                }
                blocks
            },
            animation_data: {
                let count = r_u8(buf)? as usize;
                let mut blocks = Vec::with_capacity(count);
                for _ in 0..count {
                    blocks.push(ChildAgentUpdateAnimationDataBlock::from_bytes(buf)?);
                }
                blocks
            },
            granter_block: {
                let count = r_u8(buf)? as usize;
                let mut blocks = Vec::with_capacity(count);
                for _ in 0..count {
                    blocks.push(ChildAgentUpdateGranterBlockBlock::from_bytes(buf)?);
                }
                blocks
            },
            n_v_pair_data: {
                let count = r_u8(buf)? as usize;
                let mut blocks = Vec::with_capacity(count);
                for _ in 0..count {
                    blocks.push(ChildAgentUpdateNVPairDataBlock::from_bytes(buf)?);
                }
                blocks
            },
            visual_param: {
                let count = r_u8(buf)? as usize;
                let mut blocks = Vec::with_capacity(count);
                for _ in 0..count {
                    blocks.push(ChildAgentUpdateVisualParamBlock::from_bytes(buf)?);
                }
                blocks
            },
            agent_access: {
                let count = r_u8(buf)? as usize;
                let mut blocks = Vec::with_capacity(count);
                for _ in 0..count {
                    blocks.push(ChildAgentUpdateAgentAccessBlock::from_bytes(buf)?);
                }
                blocks
            },
            agent_info: {
                let count = r_u8(buf)? as usize;
                let mut blocks = Vec::with_capacity(count);
                for _ in 0..count {
                    blocks.push(ChildAgentUpdateAgentInfoBlock::from_bytes(buf)?);
                }
                blocks
            },
            agent_inventory_host: {
                let count = r_u8(buf)? as usize;
                let mut blocks = Vec::with_capacity(count);
                for _ in 0..count {
                    blocks.push(ChildAgentUpdateAgentInventoryHostBlock::from_bytes(buf)?);
                }
                blocks
            },
        };
        Ok(packet)
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ChildAgentUpdateAgentDataBlock {
    pub region_handle: u64,
    pub viewer_circuit_code: u32,
    pub agent_i_d: UUID,
    pub session_i_d: UUID,
    pub agent_pos: Vector3,
    pub agent_vel: Vector3,
    pub center: Vector3,
    pub size: Vector3,
    pub at_axis: Vector3,
    pub left_axis: Vector3,
    pub up_axis: Vector3,
    pub changed_grid: bool,
    pub far: f32,
    pub aspect: f32,
    pub throttles: Vec<u8>,
    pub locomotion_state: u32,
    pub head_rotation: Quaternion,
    pub body_rotation: Quaternion,
    pub control_flags: u32,
    pub energy_level: f32,
    pub god_level: u8,
    pub always_run: bool,
    pub prey_agent: UUID,
    pub agent_access: u8,
    pub agent_textures: Vec<u8>,
    pub active_group_i_d: UUID,
}

impl ChildAgentUpdateAgentDataBlock {
    pub fn serialize(&self, buf: &mut BytesMut) {
        buf.put_u64_le(self.region_handle);
        buf.put_u32_le(self.viewer_circuit_code);
        buf.put_slice(self.agent_i_d.as_bytes());
        buf.put_slice(self.session_i_d.as_bytes());
        buf.put_f32_le(self.agent_pos.x);
        buf.put_f32_le(self.agent_pos.y);
        buf.put_f32_le(self.agent_pos.z);
        buf.put_f32_le(self.agent_vel.x);
        buf.put_f32_le(self.agent_vel.y);
        buf.put_f32_le(self.agent_vel.z);
        buf.put_f32_le(self.center.x);
        buf.put_f32_le(self.center.y);
        buf.put_f32_le(self.center.z);
        buf.put_f32_le(self.size.x);
        buf.put_f32_le(self.size.y);
        buf.put_f32_le(self.size.z);
        buf.put_f32_le(self.at_axis.x);
        buf.put_f32_le(self.at_axis.y);
        buf.put_f32_le(self.at_axis.z);
        buf.put_f32_le(self.left_axis.x);
        buf.put_f32_le(self.left_axis.y);
        buf.put_f32_le(self.left_axis.z);
        buf.put_f32_le(self.up_axis.x);
        buf.put_f32_le(self.up_axis.y);
        buf.put_f32_le(self.up_axis.z);
        buf.put_u8(if self.changed_grid { 1 } else { 0 });
        buf.put_f32_le(self.far);
        buf.put_f32_le(self.aspect);
        buf.put_u8(self.throttles.len() as u8);
        buf.put_slice(&self.throttles);
        buf.put_u32_le(self.locomotion_state);
        buf.put_f32_le(self.head_rotation.x);
        buf.put_f32_le(self.head_rotation.y);
        buf.put_f32_le(self.head_rotation.z);
        buf.put_f32_le(self.body_rotation.x);
        buf.put_f32_le(self.body_rotation.y);
        buf.put_f32_le(self.body_rotation.z);
        buf.put_u32_le(self.control_flags);
        buf.put_f32_le(self.energy_level);
        buf.put_u8(self.god_level);
        buf.put_u8(if self.always_run { 1 } else { 0 });
        buf.put_slice(self.prey_agent.as_bytes());
        buf.put_u8(self.agent_access);
        buf.put_u16_le(self.agent_textures.len() as u16);
        buf.put_slice(&self.agent_textures);
        buf.put_slice(self.active_group_i_d.as_bytes());
    }

    pub fn from_bytes(buf: &mut Bytes) -> Result<Self, io::Error> {
        Ok(ChildAgentUpdateAgentDataBlock {
            region_handle: r_u64_le(buf)?,
            viewer_circuit_code: r_u32_le(buf)?,
            agent_i_d: {
                let mut bytes = [0u8; 16];
                r_copy(buf, &mut bytes)?;
                UUID::from_bytes(bytes)
            },
            session_i_d: {
                let mut bytes = [0u8; 16];
                r_copy(buf, &mut bytes)?;
                UUID::from_bytes(bytes)
            },
            agent_pos: Vector3::new(r_f32_le(buf)?, r_f32_le(buf)?, r_f32_le(buf)?),
            agent_vel: Vector3::new(r_f32_le(buf)?, r_f32_le(buf)?, r_f32_le(buf)?),
            center: Vector3::new(r_f32_le(buf)?, r_f32_le(buf)?, r_f32_le(buf)?),
            size: Vector3::new(r_f32_le(buf)?, r_f32_le(buf)?, r_f32_le(buf)?),
            at_axis: Vector3::new(r_f32_le(buf)?, r_f32_le(buf)?, r_f32_le(buf)?),
            left_axis: Vector3::new(r_f32_le(buf)?, r_f32_le(buf)?, r_f32_le(buf)?),
            up_axis: Vector3::new(r_f32_le(buf)?, r_f32_le(buf)?, r_f32_le(buf)?),
            changed_grid: r_u8(buf)? != 0,
            far: r_f32_le(buf)?,
            aspect: r_f32_le(buf)?,
            throttles: {
                let len = r_u8(buf)? as usize;
                let mut data = vec![0u8; len];
                r_copy(buf, &mut data)?;
                data
            },
            locomotion_state: r_u32_le(buf)?,
            head_rotation: {
                let x = r_f32_le(buf)?;
                let y = r_f32_le(buf)?;
                let z = r_f32_le(buf)?;
                let xyzsum = 1.0 - x * x - y * y - z * z;
                let w = if xyzsum > 0.0 { xyzsum.sqrt() } else { 0.0 };
                Quaternion::new(x, y, z, w)
            },
            body_rotation: {
                let x = r_f32_le(buf)?;
                let y = r_f32_le(buf)?;
                let z = r_f32_le(buf)?;
                let xyzsum = 1.0 - x * x - y * y - z * z;
                let w = if xyzsum > 0.0 { xyzsum.sqrt() } else { 0.0 };
                Quaternion::new(x, y, z, w)
            },
            control_flags: r_u32_le(buf)?,
            energy_level: r_f32_le(buf)?,
            god_level: r_u8(buf)?,
            always_run: r_u8(buf)? != 0,
            prey_agent: {
                let mut bytes = [0u8; 16];
                r_copy(buf, &mut bytes)?;
                UUID::from_bytes(bytes)
            },
            agent_access: r_u8(buf)?,
            agent_textures: {
                let len = r_u16_le(buf)? as usize;
                let mut data = vec![0u8; len];
                r_copy(buf, &mut data)?;
                data
            },
            active_group_i_d: {
                let mut bytes = [0u8; 16];
                r_copy(buf, &mut bytes)?;
                UUID::from_bytes(bytes)
            },
        })
    }
}

