#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ScriptSensorRequestRequesterBlock {
    pub source_i_d: UUID,
    pub request_i_d: UUID,
    pub search_i_d: UUID,
    pub search_pos: Vector3,
    pub search_dir: Quaternion,
    pub search_name: Vec<u8>,
    pub r#type: i32,
    pub range: f32,
    pub arc: f32,
    pub region_handle: u64,
    pub search_regions: u8,
}

impl ScriptSensorRequestRequesterBlock {
    pub fn serialize(&self, buf: &mut BytesMut) {
        buf.put_slice(self.source_i_d.as_bytes());
        buf.put_slice(self.request_i_d.as_bytes());
        buf.put_slice(self.search_i_d.as_bytes());
        buf.put_f32_le(self.search_pos.x);
        buf.put_f32_le(self.search_pos.y);
        buf.put_f32_le(self.search_pos.z);
        buf.put_f32_le(self.search_dir.x);
        buf.put_f32_le(self.search_dir.y);
        buf.put_f32_le(self.search_dir.z);
        buf.put_u8(self.search_name.len() as u8);
        buf.put_slice(&self.search_name);
        buf.put_i32_le(self.r#type);
        buf.put_f32_le(self.range);
        buf.put_f32_le(self.arc);
        buf.put_u64_le(self.region_handle);
        buf.put_u8(self.search_regions);
    }

    pub fn from_bytes(buf: &mut Bytes) -> Result<Self, io::Error> {
        Ok(ScriptSensorRequestRequesterBlock {
            source_i_d: {
                let mut bytes = [0u8; 16];
                r_copy(buf, &mut bytes)?;
                UUID::from_bytes(bytes)
            },
            request_i_d: {
                let mut bytes = [0u8; 16];
                r_copy(buf, &mut bytes)?;
                UUID::from_bytes(bytes)
            },
            search_i_d: {
                let mut bytes = [0u8; 16];
                r_copy(buf, &mut bytes)?;
                UUID::from_bytes(bytes)
            },
            search_pos: Vector3::new(r_f32_le(buf)?, r_f32_le(buf)?, r_f32_le(buf)?),
            search_dir: {
                let x = r_f32_le(buf)?;
                let y = r_f32_le(buf)?;
                let z = r_f32_le(buf)?;
                let xyzsum = 1.0 - x * x - y * y - z * z;
                let w = if xyzsum > 0.0 { xyzsum.sqrt() } else { 0.0 };
                Quaternion::new(x, y, z, w)
            },
            search_name: {
                let len = r_u8(buf)? as usize;
                let mut data = vec![0u8; len];
                r_copy(buf, &mut data)?;
                data
            },
            r#type: r_i32_le(buf)?,
            range: r_f32_le(buf)?,
            arc: r_f32_le(buf)?,
            region_handle: r_u64_le(buf)?,
            search_regions: r_u8(buf)?,
        })
    }
}

/// ScriptSensorReply Packet
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ScriptSensorReplyPacket {
    pub header: Header,
    pub requester: ScriptSensorReplyRequesterBlock,
    pub sensed_data: Vec<ScriptSensorReplySensedDataBlock>,
}

impl Packet for ScriptSensorReplyPacket {
    fn packet_type(&self) -> PacketType {
        PacketType::ScriptSensorReply
    }
    fn serialize(&self, buf: &mut BytesMut) {
        self.header.serialize(buf);
        self.requester.serialize(buf);
        buf.put_u8(self.sensed_data.len() as u8);
        for block in &self.sensed_data {
            block.serialize(buf);
        }
        self.header.write_acks(buf);
    }

    fn from_bytes(header: Header, buf: &mut Bytes) -> Result<Self, io::Error> {
        let packet = ScriptSensorReplyPacket {
            header,
            requester: ScriptSensorReplyRequesterBlock::from_bytes(buf)?,
            sensed_data: {
                let count = r_u8(buf)? as usize;
                let mut blocks = Vec::with_capacity(count);
                for _ in 0..count {
                    blocks.push(ScriptSensorReplySensedDataBlock::from_bytes(buf)?);
                }
                blocks
            },
        };
        Ok(packet)
    }
}

