/// DeRezObject Packet
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DeRezObjectPacket {
    pub header: Header,
    pub agent_data: DeRezObjectAgentDataBlock,
    pub agent_block: DeRezObjectAgentBlockBlock,
    pub object_data: Vec<DeRezObjectObjectDataBlock>,
}

impl Packet for DeRezObjectPacket {
    fn packet_type(&self) -> PacketType {
        PacketType::DeRezObject
    }
    fn serialize(&self, buf: &mut BytesMut) {
        self.header.serialize(buf);
        self.agent_data.serialize(buf);
        self.agent_block.serialize(buf);
        buf.put_u8(self.object_data.len() as u8);
        for block in &self.object_data {
            block.serialize(buf);
        }
        self.header.write_acks(buf);
    }

    fn from_bytes(header: Header, buf: &mut Bytes) -> Result<Self, io::Error> {
        let packet = DeRezObjectPacket {
            header,
            agent_data: DeRezObjectAgentDataBlock::from_bytes(buf)?,
            agent_block: DeRezObjectAgentBlockBlock::from_bytes(buf)?,
            object_data: {
                let count = r_u8(buf)? as usize;
                let mut blocks = Vec::with_capacity(count);
                for _ in 0..count {
                    blocks.push(DeRezObjectObjectDataBlock::from_bytes(buf)?);
                }
                blocks
            },
        };
        Ok(packet)
    }
}

