#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AcceptCallingCardPacket {
    pub header: Header,
    pub agent_data: AcceptCallingCardAgentDataBlock,
    pub transaction_block: AcceptCallingCardTransactionBlockBlock,
    pub folder_data: Vec<AcceptCallingCardFolderDataBlock>,
}

impl Packet for AcceptCallingCardPacket {
    fn packet_type(&self) -> PacketType {
        PacketType::AcceptCallingCard
    }
    fn serialize(&self, buf: &mut BytesMut) {
        self.header.serialize(buf);
        self.agent_data.serialize(buf);
        self.transaction_block.serialize(buf);
        buf.put_u8(self.folder_data.len() as u8);
        for block in &self.folder_data {
            block.serialize(buf);
        }
        self.header.write_acks(buf);
    }

    fn from_bytes(header: Header, buf: &mut Bytes) -> Result<Self, io::Error> {
        let packet = AcceptCallingCardPacket {
            header,
            agent_data: AcceptCallingCardAgentDataBlock::from_bytes(buf)?,
            transaction_block: AcceptCallingCardTransactionBlockBlock::from_bytes(buf)?,
            folder_data: {
                let count = r_u8(buf)? as usize;
                let mut blocks = Vec::with_capacity(count);
                for _ in 0..count {
                    blocks.push(AcceptCallingCardFolderDataBlock::from_bytes(buf)?);
                }
                blocks
            },
        };
        Ok(packet)
    }
}

