/// SimCrashed Packet
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SimCrashedPacket {
    pub header: Header,
    pub data: SimCrashedDataBlock,
    pub users: Vec<SimCrashedUsersBlock>,
}

impl Packet for SimCrashedPacket {
    fn packet_type(&self) -> PacketType {
        PacketType::SimCrashed
    }
    fn serialize(&self, buf: &mut BytesMut) {
        self.header.serialize(buf);
        self.data.serialize(buf);
        buf.put_u8(self.users.len() as u8);
        for block in &self.users {
            block.serialize(buf);
        }
        self.header.write_acks(buf);
    }

    fn from_bytes(header: Header, buf: &mut Bytes) -> Result<Self, io::Error> {
        let packet = SimCrashedPacket {
            header,
            data: SimCrashedDataBlock::from_bytes(buf)?,
            users: {
                let count = r_u8(buf)? as usize;
                let mut blocks = Vec::with_capacity(count);
                for _ in 0..count {
                    blocks.push(SimCrashedUsersBlock::from_bytes(buf)?);
                }
                blocks
            },
        };
        Ok(packet)
    }
}

