#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CreateGroupRequestExtendedGroupDataBlock {
    pub name: Vec<u8>,
    pub charter: Vec<u8>,
    pub show_in_list: bool,
    pub insignia_i_d: UUID,
    pub membership_fee: i32,
    pub open_enrollment: bool,
    pub allow_publish: bool,
    pub mature_publish: bool,
}

impl CreateGroupRequestExtendedGroupDataBlock {
    pub fn serialize(&self, buf: &mut BytesMut) {
        buf.put_u8(self.name.len() as u8);
        buf.put_slice(&self.name);
        buf.put_u16_le(self.charter.len() as u16);
        buf.put_slice(&self.charter);
        buf.put_u8(if self.show_in_list { 1 } else { 0 });
        buf.put_slice(self.insignia_i_d.as_bytes());
        buf.put_i32_le(self.membership_fee);
        buf.put_u8(if self.open_enrollment { 1 } else { 0 });
        buf.put_u8(if self.allow_publish { 1 } else { 0 });
        buf.put_u8(if self.mature_publish { 1 } else { 0 });
    }

    pub fn from_bytes(buf: &mut Bytes) -> Result<Self, io::Error> {
        Ok(CreateGroupRequestExtendedGroupDataBlock {
            name: {
                let len = r_u8(buf)? as usize;
                let mut data = vec![0u8; len];
                r_copy(buf, &mut data)?;
                data
            },
            charter: {
                let len = r_u16_le(buf)? as usize;
                let mut data = vec![0u8; len];
                r_copy(buf, &mut data)?;
                data
            },
            show_in_list: r_u8(buf)? != 0,
            insignia_i_d: {
                let mut bytes = [0u8; 16];
                r_copy(buf, &mut bytes)?;
                UUID::from_bytes(bytes)
            },
            membership_fee: r_i32_le(buf)?,
            open_enrollment: r_u8(buf)? != 0,
            allow_publish: r_u8(buf)? != 0,
            mature_publish: r_u8(buf)? != 0,
        })
    }
}

/// GameControlInput Packet
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GameControlInputPacket {
    pub header: Header,
    pub agent_data: GameControlInputAgentDataBlock,
    pub axis_data: Vec<GameControlInputAxisDataBlock>,
    pub button_data: Vec<GameControlInputButtonDataBlock>,
}

impl Packet for GameControlInputPacket {
    fn packet_type(&self) -> PacketType {
        PacketType::GameControlInput
    }
    fn serialize(&self, buf: &mut BytesMut) {
        self.header.serialize(buf);
        self.agent_data.serialize(buf);
        buf.put_u8(self.axis_data.len() as u8);
        for block in &self.axis_data {
            block.serialize(buf);
        }
        buf.put_u8(self.button_data.len() as u8);
        for block in &self.button_data {
            block.serialize(buf);
        }
        self.header.write_acks(buf);
    }

    fn from_bytes(header: Header, buf: &mut Bytes) -> Result<Self, io::Error> {
        let packet = GameControlInputPacket {
            header,
            agent_data: GameControlInputAgentDataBlock::from_bytes(buf)?,
            axis_data: {
                let count = r_u8(buf)? as usize;
                let mut blocks = Vec::with_capacity(count);
                for _ in 0..count {
                    blocks.push(GameControlInputAxisDataBlock::from_bytes(buf)?);
                }
                blocks
            },
            button_data: {
                let count = r_u8(buf)? as usize;
                let mut blocks = Vec::with_capacity(count);
                for _ in 0..count {
                    blocks.push(GameControlInputButtonDataBlock::from_bytes(buf)?);
                }
                blocks
            },
        };
        Ok(packet)
    }
}

