#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn decodes_a_zerocoded_low_frequency_message_id() {
        let request = DirFindQueryPacket {
            header: Header {
                reliable: true,
                sequence: 7,
                frequency: PacketFrequency::Low,
                id: 31,
                ..Default::default()
            },
            agent_data: DirFindQueryAgentDataBlock {
                agent_i_d: UUID::default(),
                session_i_d: UUID::default(),
            },
            query_data: DirFindQueryQueryDataBlock {
                query_i_d: UUID::default(),
                query_text: b"jesus\0".to_vec(),
                query_flags: 1,
                query_start: 0,
            },
        };

        let mut encoded = BytesMut::new();
        Packet::serialize(&request, &mut encoded);
        assert_ne!(encoded[0] & Header::MSG_ZEROCODED, 0);

        let encoded = encoded.freeze();
        assert!(matches!(
            decode_packet(encoded.clone()),
            Ok(WrappedPacket::DirFindQuery(_))
        ));
    }
}
